from collections import defaultdict, deque

def get_order(graph, start):
    order = []
    stack = [(start, None)]
    while stack:
        node, parent = stack.pop()
        if node != start:
            order.append(node)
        children = graph[node]
        children.sort(reverse=True)
        for child in children:
            if child != parent:
                stack.append((child, node))
    return order

